<!-- wp:wdl/lw-step-2 {"bgGradient":"#2f3437","ulMaxWidth":760,"fontH3":"Shippori Mincho","fontWeightH3":"500","colorLiSvg":"#2f3437"} -->
<div class="wp-block-wdl-lw-step-2 lw-step-2"><ul class="lw-step-2__inner" style="max-width:760px"><li class="lw-step-2__li" style="border-color:#2f3437;border-width:1px"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">カウンセリング</h3><p data-lw_font_set="" style="font-weight:">肌の状態と、いま気になっていることを伺います。今日どこまでできるかを、はじめにお伝えします。メイクのままお越しください。</p><span class="icon" style="fill:#2f3437"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-2__li" style="border-color:#2f3437;border-width:1px"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">クレンジング</h3><p data-lw_font_set="" style="font-weight:">メイクと皮脂を落とします。ここを丁寧にするほど、あとの手当てが届きます。蒸しタオルで温めながら進めます。</p><span class="icon" style="fill:#2f3437"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-2__li" style="border-color:#2f3437;border-width:1px"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">施術</h3><p data-lw_font_set="" style="font-weight:">その日の肌に合わせて内容を組み立てます。こちらからお声がけはいたしません。眠ってしまう方がほとんどです。</p><span class="icon" style="fill:#2f3437"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-2__li" style="border-color:#2f3437;border-width:1px"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">仕上げとご提案</h3><p data-lw_font_set="" style="font-weight:">肌を整えてお帰りいただきます。ご自宅でのお手入れを、いまお使いの化粧品に合わせてお伝えします。</p><span class="icon" style="fill:#2f3437"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li></ul></div>
<!-- /wp:wdl/lw-step-2 -->

