<!-- wp:wdl/lw-voice-1 {"h2FontSet":"Shippori Mincho","h2FontWeight":"500","h2TextColor":"#2f3437","nameBackgroundColor":"#2f3437","nameFontSet":"","h3TextColor":"#2f3437","h3FontSet":"Shippori Mincho","pTextColor":"#3a3733","pFontSet":"","backgroundColor":"#f4f1ec"} -->
<div class="wp-block-wdl-lw-voice-1 lw-voice-1" style="background-color:#f4f1ec"><h2 class="lw-voice-1__title" style="font-weight:500;color:#2f3437" data-lw_font_set="Shippori Mincho">お客様の声</h2><ul class="lw-voice-1__ul"><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">鎌倉市 40代 K様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">押し売りが一切ないので、安心して通っています。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">化粧のりが悪いのは年齢のせいだと思っていました。1回目の翌朝にファンデーションがすっと伸びて驚きました。静かに受けられるのもありがたいです。</p></div></li><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">横浜市 50代 M様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">帰り道の空気まで違って感じました。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">会話をしなくていいと最初に言っていただけたので、ずっと目を閉じていました。肩の力が抜けて、終わったあとに首が軽くなっているのが自分でも分かりました。</p></div></li><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">藤沢市 30代 A様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">通う理由が、肌のことだけではなくなりました。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">最初は毛穴が気になって伺いました。いまは月に一度、ここで何も考えない時間をとるために予約しています。帰りに小町通りを歩くところまでが習慣です。</p></div></li></ul></div>
<!-- /wp:wdl/lw-voice-1 -->

